import { renderElement, type PartProps } from "@ui-sdk/react/primitive"

import { cn } from "@/lib/utils"

// motion-reduce stops the pulse outright: the theme's shortened durations would turn an infinite loop into flicker.
function Skeleton({ className, render, ...props }: PartProps<"div">) {
  return renderElement(
    "div",
    {
      "data-slot": "skeleton",
      "aria-hidden": true,
      className: cn("animate-pulse rounded-control bg-foreground/10 motion-reduce:animate-none", className),
      ...props,
    },
    render,
  )
}

export { Skeleton }
